interface Scored { int score(); }
class First implements Scored { public int score() { return 3; } }
class Second implements Scored { public int score() { return 8; } }
class Box<T> {
    private final T value;
    Box(T value) { this.value = value; }
    T get() { return value; }
}
public class Main {
    public static void main(String[] args) {
        int sum = 0;
        for (Scored item : new Scored[]{new First(), new Second()}) sum += item.score();
        System.out.println(sum);
        System.out.println(new Box<Integer>(5).get());
    }
}

